using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageEdgeCaseTests
{
    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            [GeneratedMessagePackResolver]
            partial class MyResolver { }

            [MessagePackObject]
            public class MyObject
            {
                [Key(0)]
                public int Value { get; set; }
            }
        }
        """;

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task FormatterIsDecoratedOnSupportedTfmSymbols(string symbol)
    {
        GeneratorDriverRunResult result = await RunGeneratorAsync(symbol);

        var formatterClasses = result.GeneratedTrees
            .SelectMany(t => t.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>())
            .Where(c => c.Identifier.ValueText.Contains("MyObject") && c.Identifier.ValueText.EndsWith("Formatter", StringComparison.Ordinal))
            .ToList();

        Assert.NotEmpty(formatterClasses);
        foreach (ClassDeclarationSyntax cls in formatterClasses)
        {
            bool hasAttribute = cls.AttributeLists.SelectMany(a => a.Attributes).Any(a => a.Name.ToString().Contains("ExcludeFromCodeCoverage"));
            Assert.True(hasAttribute, $"Formatter '{cls.Identifier.ValueText}' lacks ExcludeFromCodeCoverage when {symbol} is defined, although the attribute exists on that target.");
        }
    }

    [Fact]
    public async Task ResolverFileIsDecorated()
    {
        GeneratorDriverRunResult result = await RunGeneratorAsync();

        var resolverSources = result.Results
            .SelectMany(r => r.GeneratedSources)
            .Where(s => s.HintName.EndsWith("MyResolver.g.cs", StringComparison.Ordinal))
            .ToList();

        Assert.NotEmpty(resolverSources);
        foreach (GeneratedSourceResult src in resolverSources)
        {
            Assert.Contains("ExcludeFromCodeCoverage", src.SourceText.ToString(), StringComparison.Ordinal);
        }
    }

    private static async Task<GeneratorDriverRunResult> RunGeneratorAsync(params string[] preprocessorSymbols)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: preprocessorSymbols);
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> references = frameworkRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);
        return driver.GetRunResult();
    }
}
